/* 학습 해설
 * 현재 스택 위 객체 판별·tag 제거와 반열린 범위
 * 태스크 스택 포인터·수명 참조·thread info 배치·끝 magic·tag·주소 판별·설정별 stub와 override의 사용 원리를 이해합니다.
 * object_is_on_stack은 current stack pointer를 얻고 kasan_reset_tag(obj)로 태그를 제거한 뒤 obj>=stack과 obj<stack+THREAD_SIZE를 검사합니다. 현재 스택의 주소 위치를 판별하는 함수이며 다른 task를 조회하는 인자는 없습니다. raw tagged pointer를 그대로 경계 비교하지 않게 하는 순서입니다.
 * 유효 배열의 low·high-1·high를 각각 true·true·false로 계산하고 tag mask 모델의 위치도 확인합니다. 실제 KASAN tag 규칙과 CPU pointer 표현은 별도 helper이며 모델의 상위 byte mask로 모든 구현을 대체하지 않습니다.
 */
static inline int object_is_on_stack(const void *obj)
{
	void *stack = task_stack_page(current);

	obj = kasan_reset_tag(obj);
	return (obj >= stack) && (obj < (stack + THREAD_SIZE));
}

