/* 학습 해설
 * PAC setter의 current update·저장 task와 실행 register 분리
 * pointer authentication의 key·주소 bit·초기화·설치·enable·부분 갱신·사용자 API·ABI·가상화 계약과 사용 원리를 이해합니다.
 * setter는 tsk.thread.sctlr_user를 갱신하고 tsk==current인 경우에만 update_sctlr_el1을 호출한 뒤 preempt_enable합니다. 다른 task의 저장 상태를 변경하는 것과 지금 실행 중인 CPU register를 바꾸는 일이 다릅니다. preempt 구간은 getter의 실제 값 읽기·하드웨어 갱신 순서와 함께 봅니다.
 * current·other의 같은 유효 요청에서 저장 상태는 모두 갱신되지만 update callback은 current만 1회인지 확인합니다. fixture는 disable/enable 균형을 모델링하며 실제 CPU migration·SMP 동기화는 수행하지 않습니다.
 */
int ptrauth_set_enabled_keys(struct task_struct *tsk, unsigned long keys,
			     unsigned long enabled)
{
	u64 sctlr;

	if (!system_supports_address_auth())
		return -EINVAL;

	if (is_compat_thread(task_thread_info(tsk)))
		return -EINVAL;

	if ((keys & ~PR_PAC_ENABLED_KEYS_MASK) || (enabled & ~keys))
		return -EINVAL;

	preempt_disable();
	sctlr = tsk->thread.sctlr_user;
	sctlr &= ~arg_to_enxx_mask(keys);
	sctlr |= arg_to_enxx_mask(enabled);
	tsk->thread.sctlr_user = sctlr;
	if (tsk == current)
		update_sctlr_el1(sctlr);
	preempt_enable();

	return 0;
}

/* 학습 해설
 * PAC enabled getter·저장 상태를 API mask로 반환
 * pointer authentication의 key·주소 bit·초기화·설치·enable·부분 갱신·사용자 API·ABI·가상화 계약과 사용 원리를 이해합니다.
 * getter도 address 지원·non-compat을 확인하고 저장된 sctlr_user의 네 EN bit를 PR flag로 변환해 반환합니다. unrelated SCTLR bit는 결과에 넣지 않으며 새 key를 생성하거나 register를 직접 읽는 함수가 아닙니다. bit 변환은 setter의 반대 방향 연결입니다.
 * 초기 네-bit 상태 0~15를 각각 대응 flag로 읽고 지원 없는 입력은 -EINVAL을 구별하세요. fixture의 getter 검산은 순차 저장 상태이며 실제 동시 task 상태 snapshot까지 증명하지 않습니다.
 */
int ptrauth_get_enabled_keys(struct task_struct *tsk)
{
	int retval = 0;

	if (!system_supports_address_auth())
		return -EINVAL;

	if (is_compat_thread(task_thread_info(tsk)))
		return -EINVAL;

	if (tsk->thread.sctlr_user & SCTLR_ELx_ENIA)
		retval |= PR_PAC_APIAKEY;
	if (tsk->thread.sctlr_user & SCTLR_ELx_ENIB)
		retval |= PR_PAC_APIBKEY;
	if (tsk->thread.sctlr_user & SCTLR_ELx_ENDA)
		retval |= PR_PAC_APDAKEY;
	if (tsk->thread.sctlr_user & SCTLR_ELx_ENDB)
		retval |= PR_PAC_APDBKEY;

	return retval;
}
